# R1: READ the variables x, y, z each taking values from {1, 2, 3}
# R2: READ the constraints C1: x != y, C2: y != z, C3: z != x, C4: x + y + z = 4, C5: x >= y, C6: y >= z
# R3: SOLVE the constraint satisfaction problem for all possible assignments
# R4: RETURN all assignments that satisfy every constraint
# R5: IF no assignments satisfy all constraints THEN RETURN a statement that no solution exists together with a concise explanation of the conflicting constraints

import json
from itertools import product

solutions = []
for x, y, z in product([1, 2, 3], repeat=3):
    if x != y and y != z and z != x:
        if x + y + z == 4:
            if x >= y and y >= z:
                solutions.append({'x': x, 'y': y, 'z': z})

if solutions:
    print('Solutions:')
    for sol in solutions:
        print(sol)
else:
    print('No solution exists. Constraints conflict: C4 forces sum 4 while C5 and C6 together with distinctness make this impossible.')

# Witness output
witness_data = {'solutions': solutions}
print('WITNESS: ' + json.dumps({'polarity': 'positive', 'evidence': {'path': 'execution://witness'}, 'data': witness_data}))
